package com.game_manager.gm.workflow; import com.game_manager.gm.common.error.ApplicationException; import com.game_manager.gm.workflow.dto.WorkflowDefinitionRequest; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component;
@Component public class WorkflowDefinitionValidator {private static final Set<String> ROLES=Set.of("ADMIN","OWNER","SUBMITTER");private static final Set<String>ACTIONS=Set.of("APPROVE","REJECT","RETURN","SUBMIT","CANCEL");private static final Set<String>TERMINALS=Set.of("APPROVED","REJECTED","CANCELLED");
 public void validate(WorkflowDefinitionRequest r){Set<String> keys=new HashSet<>();for(var s:r.steps()){if(!keys.add(s.key())||!ROLES.contains(s.role())||s.reminderHours()>=s.dueHours()||(s.escalationRole()!=null&&!ROLES.contains(s.escalationRole())))bad();}if(!keys.contains(r.initialStep()))bad();Set<String>from=new HashSet<>();for(var t:r.transitions()){if(!keys.contains(t.from())||!ACTIONS.contains(t.action())||(!keys.contains(t.target())&&!TERMINALS.contains(t.target()))||!from.add(t.from()+":"+t.action()))bad();}if(!from.contains(r.initialStep()+":APPROVE"))bad();for(String key:keys)if(r.transitions().stream().noneMatch(t->t.from().equals(key)))bad();}
 private void bad(){throw new ApplicationException(HttpStatus.BAD_REQUEST,"Workflow definition contains unsupported or inconsistent primitives");}}
